const ALLOWED = ["facebook","instagram","linkedin","twitter","threads","bluesky","tiktok","youtube"];
function parsePlatforms(raw) {
  const list = (Array.isArray(raw) ? raw : String(raw || '').split(','))
    .map((p) => String(p).trim().toLowerCase())
    .filter(Boolean)
    .map((p) => (p === 'x' ? 'twitter' : p));
  const unknown = list.filter((p) => !ALLOWED.includes(p));
  if (unknown.length) throw new Error('Socialync cannot post to: ' + unknown.join(', ') + '. Use: ' + ALLOWED.join(', ') + '.');
  if (!list.length) throw new Error('Set at least one platform in the Settings node.');
  return [...new Set(list)];
}
function fit(text, max) {
  const t = String(text).replace(/[ \t]+\n/g, '\n').trim();
  if (t.length <= max) return t;
  const cut = t.slice(0, Math.max(0, max - 3));
  return cut.replace(/\s+\S*$/, '') + '...';
}
// Socialync accepts 1 to 255 letters, digits and _ . : - in an Idempotency Key.
function safeKey(prefix, value) {
  return (prefix + ':' + String(value)).replace(/[^A-Za-z0-9_.:-]/g, '-').slice(0, 200);
}
const s = $('Settings').item.json;
const head = $input.item.json || {};
if (!s.videoId) throw new Error('Could not find the video ID in the feed item. Check the feed address.');
const thumbnail = 'https://i.ytimg.com/vi/' + s.videoId + '/' + (Number(head.statusCode) === 200 ? 'maxresdefault' : 'hqdefault') + '.jpg';
const title = String(s.videoTitle || '').trim();
const link = String(s.videoLink || '').trim();
const intro = String(s.introLine || 'New video:').trim();
const igLine = String(s.instagramLinkLine || 'Link in bio.').trim();
const platforms = parsePlatforms(s.platforms).filter((p) => !['tiktok', 'youtube'].includes(p));
if (!platforms.length) throw new Error('Choose at least one platform other than tiktok and youtube in Settings.');

const short = (max) => fit(intro + ' ' + title, Math.max(40, max - link.length - 2)) + '\n\n' + link;
const custom = {};
for (const p of platforms) {
  if (p === 'bluesky') custom.bluesky = { customCaption: short(300) };
  if (p === 'threads') custom.threads = { customCaption: short(500) };
  if (p === 'twitter') custom.twitter = { customCaption: short(280) };
  if (p === 'instagram') custom.instagram = { customCaption: fit(intro + ' ' + title, 2000) + '\n\n' + igLine };
}
const delay = Math.max(5, Number(s.publishDelayMinutes) || 30);
return { json: {
  profileId: String(s.profileId || '').trim(),
  platforms,
  caption: intro + ' ' + title + '\n\nWatch it here: ' + link,
  imageUrl: thumbnail,
  platformSpecificSettings: Object.keys(custom).length ? JSON.stringify(custom) : '',
  scheduledAt: new Date(Date.now() + delay * 60000).toISOString(),
  idempotencyKey: safeKey('youtube', s.videoId),
} };

const post = $('Build the post').item.json;
const check = $input.item.json || {};
const results = Array.isArray(check.platforms) ? check.platforms : [];
const ready = results.filter((p) => p.ok === true).map((p) => p.platform);
const skipped = results
  .filter((p) => p.ok !== true)
  .map((p) => p.platform + ': ' + (p.errors || []).map((e) => e.message).join(' '));
const globalProblems = (check.globalErrors || []).map((e) => e.message);
let custom = {};
try { custom = post.platformSpecificSettings ? JSON.parse(post.platformSpecificSettings) : {}; } catch (e) { custom = {}; }
for (const key of Object.keys(custom)) if (!ready.includes(key)) delete custom[key];
return { json: {
  ...post,
  ok: ready.length > 0 && globalProblems.length === 0,
  platforms: ready,
  skipped,
  problem: globalProblems.concat(skipped).join(' | '),
  platformSpecificSettings: Object.keys(custom).length ? JSON.stringify(custom) : '',
} };
